// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "adi.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// First apply j_vec (inner), then i_vec (outer) to match C layout u[i][j]
	DEFINE_PROTO_STRUCT(u_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(v_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(p_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(q_layout, j_vec ^ i_vec);
} tuning;


// initialization function
// U is n x n, with dimensions 'i' and 'j'
void init_array(auto U) {
	using namespace noarr;

	const std::size_t n = U | get_length<'i'>();
	const num_t inv_n = SCALAR_VAL(1.0) / static_cast<num_t>(n);

	// Traverse whole array; for_each chooses the natural (cache-friendly) order
	traverser(U).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		// Original formula: (i + n - j) / n
		U[state] = (static_cast<num_t>(i) +
		            static_cast<num_t>(n) -
		            static_cast<num_t>(j)) * inv_n;
	});
}


// computation kernel
// ADI time-stepping scheme on a 2D grid
// The data layout and numerical scheme are preserved; we only
//  * precompute constants used in inner loops
//  * improve traversal order and reuse traversers
//  * parallelize over the 'i' dimension using OpenMP
[[gnu::flatten, gnu::noinline]]
void kernel_adi(std::size_t tsteps, auto U, auto V, auto P, auto Q) {
	using namespace noarr;

	const std::size_t n = U | get_length<'i'>();

	num_t DX = 0, DY = 0, DT = 0;
	num_t B1 = 0, B2 = 0;
	num_t mul1 = 0, mul2 = 0;
	num_t a = 0, b = 0, c = 0, d = 0, e = 0, f = 0;

#pragma scop

	// Spatial and temporal steps
	DX = SCALAR_VAL(1.0) / (num_t)n;
	DY = SCALAR_VAL(1.0) / (num_t)n;
	DT = SCALAR_VAL(1.0) / (num_t)tsteps;

	B1 = SCALAR_VAL(2.0);
	B2 = SCALAR_VAL(1.0);

	mul1 = B1 * DT / (DX * DX);
	mul2 = B2 * DT / (DY * DY);

	// Coefficients of the implicit schemes in each direction
	a = -mul1 / SCALAR_VAL(2.0);
	b = SCALAR_VAL(1.0) + mul1;
	c = a;
	d = -mul2 / SCALAR_VAL(2.0);
	e = SCALAR_VAL(1.0) + mul2;
	f = d;

	// Precompute scalar constants used inside the innermost loops
	const num_t one            = SCALAR_VAL(1.0);
	const num_t zero           = SCALAR_VAL(0.0);
	const num_t two            = SCALAR_VAL(2.0);
	const num_t one_plus_two_d = one + two * d;
	const num_t one_plus_two_a = one + two * a;

	// Common index for the last row/column
	const std::size_t last_idx = n - 1;

	// Slices selecting interior points (1 .. n-2) in each dimension;
	// these are reused many times across traversals.
	const auto interior_i = noarr::slice<'i'>(1, n - 2);
	const auto interior_j = noarr::slice<'j'>(1, n - 2);

	for (std::size_t t = 1; t <= tsteps; t++) {
		// ------------------------------------------------------------------
		// Column sweep: implicit solve in the "vertical" direction.
		// Each iteration over 'i' (a column index in the original algorithm)
		// is independent and can be processed in parallel.
		// ------------------------------------------------------------------
		#pragma omp parallel for schedule(static)
		for (auto trav_i : noarr::traverser(U, V, P, Q)
		                       .order(interior_i ^ noarr::hoist<'i'>())) {

			const auto state_i = trav_i.state();
			const std::size_t i = get_index<'i'>(state_i);

			const std::size_t im1 = i - 1;
			const std::size_t ip1 = i + 1;

			// Traverser over interior j for this fixed i
			auto trav_ij = trav_i.order(interior_j);

			// Boundary conditions for current column i
			const num_t v0i = one;
			V[noarr::idx<'i', 'j'>(0,      i)] = v0i;
			P[noarr::idx<'i', 'j'>(i,      0)] = zero;
			Q[noarr::idx<'i', 'j'>(i,      0)] = v0i;

			// Forward sweep in j: j = 1 .. n-2
			trav_ij.for_each([&](auto state) {
				auto prev = state - noarr::idx<'j'>(1);

				const num_t denom = a * P[prev] + b;
				P[state] = -c / denom;

				const std::size_t j = get_index<'j'>(state);

				// Note: U is accessed with indices (j, i±1) exactly
				// as in the original PolyBench kernel; only the layout
				// is abstracted through noarr.
				const num_t u_j_im1 = U[noarr::idx<'i', 'j'>(j, im1)];
				const num_t u_j_i   = U[noarr::idx<'i', 'j'>(j, i)];
				const num_t u_j_ip1 = U[noarr::idx<'i', 'j'>(j, ip1)];

				Q[state] = (-d * u_j_im1
				            + one_plus_two_d * u_j_i
				            - f * u_j_ip1
				            - a * Q[prev]) / denom;
			});

			// Bottom boundary at j = n-1
			V[noarr::idx<'i', 'j'>(last_idx, i)] = one;

			// Backward sweep in j: j = n-2 .. 1
			// Implemented as a forward sweep over k = 1 .. n-2
			// with j = n-1-k, preserving the original arithmetic.
			trav_ij.for_each([&](auto state) {
				const std::size_t k = get_index<'j'>(state); // 1 .. n-2
				const std::size_t j = last_idx - k;          // n-2 .. 1

				const auto pij_state   = noarr::idx<'i', 'j'>(i, j);
				const auto vjp1i_state = noarr::idx<'i', 'j'>(j + 1, i);

				V[noarr::idx<'i', 'j'>(j, i)] =
					P[pij_state] * V[vjp1i_state] + Q[pij_state];
			});
		}

		// ------------------------------------------------------------------
		// Row sweep: implicit solve in the "horizontal" direction.
		// Again, each iteration over 'i' (row index in the original
		// algorithm) is independent and can be processed in parallel.
		// ------------------------------------------------------------------
		#pragma omp parallel for schedule(static)
		for (auto trav_i : noarr::traverser(U, V, P, Q)
		                       .order(interior_i ^ noarr::hoist<'i'>())) {

			const auto state_i = trav_i.state();
			const std::size_t i = get_index<'i'>(state_i);

			const std::size_t im1 = i - 1;
			const std::size_t ip1 = i + 1;

			auto trav_ij = trav_i.order(interior_j);

			// Boundary conditions for current row i
			const num_t ui0 = one;
			U[noarr::idx<'i', 'j'>(i, 0)] = ui0;
			P[noarr::idx<'i', 'j'>(i, 0)] = zero;
			Q[noarr::idx<'i', 'j'>(i, 0)] = ui0;

			// Forward sweep in j: j = 1 .. n-2
			trav_ij.for_each([&](auto state) {
				auto prev = state - noarr::idx<'j'>(1);

				const num_t denom = d * P[prev] + e;
				P[state] = -f / denom;

				const std::size_t j = get_index<'j'>(state);

				const num_t v_im1_j = V[noarr::idx<'i', 'j'>(im1, j)];
				const num_t v_i_j   = V[noarr::idx<'i', 'j'>(i,   j)];
				const num_t v_ip1_j = V[noarr::idx<'i', 'j'>(ip1, j)];

				Q[state] = (-a * v_im1_j
				            + one_plus_two_a * v_i_j
				            - c * v_ip1_j
				            - d * Q[prev]) / denom;
			});

			// Right boundary at j = n-1
			U[noarr::idx<'i', 'j'>(i, last_idx)] = one;

			// Backward sweep in j: j = n-2 .. 1
			trav_ij.for_each([&](auto state) {
				const std::size_t k = get_index<'j'>(state); // 1 .. n-2
				const std::size_t j = last_idx - k;          // n-2 .. 1

				const auto pij_state   = noarr::idx<'i', 'j'>(i, j);
				const auto uijp1_state = noarr::idx<'i', 'j'>(i, j + 1);

				U[pij_state] = P[pij_state] * U[uijp1_state] + Q[pij_state];
			});
		}
	}

#pragma endscop
}

} // namespace


