using num_t = DATA_TYPE;

namespace {

// Layout tuning: inner 'j' (contiguous in memory), outer 'i'
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// First apply j_vec (inner), then i_vec (outer) to match C layout u[i][j]
	DEFINE_PROTO_STRUCT(u_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(v_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(p_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(q_layout, j_vec ^ i_vec);
} tuning;

// Tuning knob: OpenMP chunk size for the outer 'i' dimension.
// This can be adjusted for specific core counts / cache sizes.
constexpr int OMP_CHUNK_I = 32;


// initialization function
//
// Uses a traverser range over dimension 'i' to allow an easy OpenMP
// parallel-for on rows. Each thread then traverses its row sequentially
// in the inner, contiguous 'j' dimension.
void init_array(auto U) {
	using namespace noarr;

	auto n = U | get_length<'i'>();
	const num_t inv_n = SCALAR_VAL(1.0) / static_cast<num_t>(n);

	auto trav     = traverser(U);
	auto range_i  = trav.template range<'i'>(); // split over outer dimension 'i'

	// Parallelize initialization over rows (independent work per row).
	// Without OpenMP, this degenerates to a plain serial loop.
#ifdef _OPENMP
#pragma omp parallel for schedule(static, OMP_CHUNK_I)
#endif
	for (std::size_t bi = 0; bi < range_i.size(); ++bi) {
		auto trav_i = range_i[bi];

		// Traverse inner, contiguous 'j' within each row.
		trav_i.for_each([&](auto state) {
			auto [i, j] = get_indices<'i', 'j'>(state);
			const num_t val = static_cast<num_t>(i + n - j) * inv_n;
			U[state] = val;
		});
	}
}


// computation kernel
//
// This is a direct translation of the ADI scheme, expressed purely in terms
// of Noarr traversers. The main optimizations applied are:
//
//  - Hoisting invariant scalars (DX, DY, DT, combined constants).
//  - Avoiding repeated construction of slice protostructures.
//  - Reusing traverser ranges over dimension 'i' and parallelizing those
//    with OpenMP.  Each iteration of the parallel loop operates on a
//    distinct row/column i and keeps the inner j-sweeps sequential
//    (necessary because of the recurrence in j).
//  - Eliminating redundant SCALAR_VAL(1.0/2.0) expressions inside the
//    hot loops by precomputing one_plus_2d and one_plus_2a.
//
[[gnu::flatten, gnu::noinline]]
void kernel_adi(std::size_t tsteps, auto U, auto V, auto P, auto Q) {
	using namespace noarr;

	auto n = U | get_length<'i'>();

	// Coefficients (initialized inside the SCoP region for polyhedral tools)
	num_t DX = 0, DY = 0, DT = 0;
	num_t B1 = 0, B2 = 0;
	num_t mul1 = 0, mul2 = 0;
	num_t a = 0, b = 0, c = 0, d = 0, e = 0, f = 0;

	// Constants hoisted outside loops
	const num_t zero = SCALAR_VAL(0.0);
	const num_t one  = SCALAR_VAL(1.0);
	const num_t two  = SCALAR_VAL(2.0);

	const num_t inv_n      = one / static_cast<num_t>(n);
	const num_t inv_tsteps = one / static_cast<num_t>(tsteps);

	// SCoP region for polyhedral tools (kept intact)
#pragma scop

	DX = inv_n;
	DY = inv_n;
	DT = inv_tsteps;
	B1 = SCALAR_VAL(2.0);
	B2 = SCALAR_VAL(1.0);
	mul1 = B1 * DT / (DX * DX);
	mul2 = B2 * DT / (DY * DY);

	a = -mul1 / SCALAR_VAL(2.0);
	b = one + mul1;
	c = a;
	d = -mul2 / SCALAR_VAL(2.0);
	e = one + mul2;
	f = d;

	// Precompute combinations that appear in every inner iteration
	const num_t one_plus_2d = one + two * d;
	const num_t one_plus_2a = one + two * a;

	// Common slices for interior points (indices 1 .. n-2)
	const auto slice_i_inner = noarr::slice<'i'>(1, n - 2);
	const auto slice_j_inner = noarr::slice<'j'>(1, n - 2);

	for (std::size_t t = 1; t <= tsteps; t++) {

		// -------------------------------------------------------------
		// Column sweep
		// -------------------------------------------------------------
		{
			auto trav_cols = traverser(U, V, P, Q).order(slice_i_inner);
			auto range_i   = trav_cols.template range<'i'>(); // interior i = 1..n-2

			// Parallelize over columns 'i'. For each column we still do
			// a sequential forward/backward sweep in 'j'.
#ifdef _OPENMP
#pragma omp parallel for schedule(static, OMP_CHUNK_I)
#endif
			for (std::size_t bi = 0; bi < range_i.size(); ++bi) {
				auto trav_i = range_i[bi];
				const auto i = get_index<'i'>(trav_i.state()); // global i in [1, n-2]

				// Boundary conditions for column i
				V[noarr::idx<'i', 'j'>(0,     i)] = one;
				P[noarr::idx<'i', 'j'>(i,     0)] = zero;
				Q[noarr::idx<'i', 'j'>(i,     0)] = V[noarr::idx<'i', 'j'>(0, i)];

				// Forward sweep in j: j = 1 .. n-2 (interior rows)
				auto trav_j = trav_i.order(slice_j_inner);
				trav_j.for_each([&](auto state) {
					auto prev = state - noarr::idx<'j'>(1);
					const auto j = get_index<'j'>(state);

					const num_t denom = a * P[prev] + b;
					P[state] = -c / denom;

					const num_t u_j_im1 = U[noarr::idx<'i', 'j'>(j, i - 1)];
					const num_t u_j_i   = U[noarr::idx<'i', 'j'>(j, i    )];
					const num_t u_j_ip1 = U[noarr::idx<'i', 'j'>(j, i + 1)];

					Q[state] = (-d * u_j_im1
					            + one_plus_2d * u_j_i
					            - f * u_j_ip1
					            - a * Q[prev]) / denom;
				});

				// Boundary at bottom row
				V[noarr::idx<'i', 'j'>(n - 1, i)] = one;

				// Backward sweep in j: j = n-2 .. 1
				// Implemented as forward sweep over k = 1 .. n-2 with j = n-1-k
				trav_j.for_each([&](auto state) {
					const auto k = get_index<'j'>(state);
					const std::size_t j = n - 1 - k; // n-2, n-3, ..., 1

					const auto pij_state   = noarr::idx<'i', 'j'>(i, j);
					const auto vjp1i_state = noarr::idx<'i', 'j'>(j + 1, i);

					V[noarr::idx<'i', 'j'>(j, i)] =
						P[pij_state] * V[vjp1i_state] + Q[pij_state];
				});
			}
		}

		// -------------------------------------------------------------
		// Row sweep
		// -------------------------------------------------------------
		{
			auto trav_rows = traverser(U, V, P, Q).order(slice_i_inner);
			auto range_i   = trav_rows.template range<'i'>(); // interior i = 1..n-2

			// Parallelize over rows 'i'. Each row is independent given V.
#ifdef _OPENMP
#pragma omp parallel for schedule(static, OMP_CHUNK_I)
#endif
			for (std::size_t bi = 0; bi < range_i.size(); ++bi) {
				auto trav_i = range_i[bi];
				const auto i = get_index<'i'>(trav_i.state()); // global i in [1, n-2]

				// Boundary conditions for row i
				U[noarr::idx<'i', 'j'>(i, 0)] = one;
				P[noarr::idx<'i', 'j'>(i, 0)] = zero;
				Q[noarr::idx<'i', 'j'>(i, 0)] = U[noarr::idx<'i', 'j'>(i, 0)];

				// Forward sweep in j: j = 1 .. n-2 (interior columns)
				auto trav_j = trav_i.order(slice_j_inner);
				trav_j.for_each([&](auto state) {
					auto prev = state - noarr::idx<'j'>(1);
					const auto j = get_index<'j'>(state);

					const num_t denom = d * P[prev] + e;
					P[state] = -f / denom;

					const num_t v_im1_j = V[noarr::idx<'i', 'j'>(i - 1, j)];
					const num_t v_i_j   = V[noarr::idx<'i', 'j'>(i,     j)];
					const num_t v_ip1_j = V[noarr::idx<'i', 'j'>(i + 1, j)];

					Q[state] = (-a * v_im1_j
					            + one_plus_2a * v_i_j
					            - c * v_ip1_j
					            - d * Q[prev]) / denom;
				});

				// Boundary at rightmost column
				U[noarr::idx<'i', 'j'>(i, n - 1)] = one;

				// Backward sweep in j: j = n-2 .. 1
				trav_j.for_each([&](auto state) {
					const auto k = get_index<'j'>(state);
					const std::size_t j = n - 1 - k; // n-2, ..., 1

					const auto pij_state   = noarr::idx<'i', 'j'>(i, j);
					const auto uijp1_state = noarr::idx<'i', 'j'>(i, j + 1);

					U[pij_state] = P[pij_state] * U[uijp1_state] + Q[pij_state];
				});
			}
		}
	}

#pragma endscop
}

