#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "adi.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// First apply j_vec (inner), then i_vec (outer) to match C layout u[i][j]
	DEFINE_PROTO_STRUCT(u_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(v_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(p_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(q_layout, j_vec ^ i_vec);
} tuning;


// initialization function
void init_array(auto U) {
	using namespace noarr;

	const std::size_t n = U | get_length<'i'>();

	// U: i x j
	traverser(U).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		U[state] = (num_t)(i + n - j) / (num_t)n;
	});
}


// computation kernel
// NOTE:
//  - All data-space traversals use Noarr traversers (including the OpenMP-parallel
//    outer loops, which iterate traverser ranges).
//  - We parallelize over the independent 'i'-dimension using OpenMP while
//    preserving the strictly sequential Thomas-sweep dependencies along 'j'.
//  - Several scalar expressions are precomputed outside the sweeps to reduce
//    arithmetic in the inner loops and to give the compiler more room for
//    vectorization.
[[gnu::flatten, gnu::noinline]]
void kernel_adi(std::size_t tsteps, auto U, auto V, auto P, auto Q) {
	using namespace noarr;

	const std::size_t n         = U | get_length<'i'>();
	const std::size_t inner_len = n - 2;      // length of the non-boundary region
	const std::size_t i_start   = 1;
	const std::size_t j_start   = 1;
	const std::size_t n_minus_1 = n - 1;

	// Precompute basic scalars once
	const num_t one  = SCALAR_VAL(1.0);
	const num_t zero = SCALAR_VAL(0.0);
	const num_t two  = SCALAR_VAL(2.0);

#pragma scop

	// Discretization & helper constants
	const num_t DX  = one / (num_t)n;
	const num_t DY  = one / (num_t)n;
	const num_t DT  = one / (num_t)tsteps;
	const num_t B1  = SCALAR_VAL(2.0);
	const num_t B2  = SCALAR_VAL(1.0);
	const num_t mul1 = B1 * DT / (DX * DX);
	const num_t mul2 = B2 * DT / (DY * DY);

	const num_t a = -mul1 / SCALAR_VAL(2.0);
	const num_t b = one + mul1;
	const num_t c = a;
	const num_t d = -mul2 / SCALAR_VAL(2.0);
	const num_t e = one + mul2;
	const num_t f = d;

	// These appear inside the sweeps, so we precompute them once
	const num_t one_plus_2d = one + two * d;
	const num_t one_plus_2a = one + two * a;

	for (std::size_t t = 1; t <= tsteps; t++) {

		// ------------------------------------------------------------------
		// Column sweep
		//
		// For each i in 1..n-2 (independent columns/rows – naming aside),
		//   we perform a forward and backward Thomas sweep along j.
		// The sweeps along j are strictly sequential, but different i
		// values are independent and can therefore be processed in parallel.
		// ------------------------------------------------------------------

		auto col_trav = traverser(U, V, P, Q)
			.order(noarr::slice<'i'>(i_start, inner_len)); // i = 1 .. n-2

		// Parallelize over the top-level 'i' traverser using OpenMP.
		// Each iteration of this loop processes a distinct i-line
		// and only touches entries with that fixed i, so there are
		// no write-write races between threads.
		#pragma omp parallel for schedule(static)
		for (auto trav_i : col_trav) {
			const auto istate = trav_i.state();
			const std::size_t i = get_index<'i'>(istate);

			// Boundary conditions for this "column" i
			V[noarr::idx<'i', 'j'>(0,        i)] = one;
			P[noarr::idx<'i', 'j'>(i,        0)] = zero;
			Q[noarr::idx<'i', 'j'>(i,        0)] = V[noarr::idx<'i', 'j'>(0, i)];

			// Restrict traversal in this thread to the inner j-range
			auto trav_i_inner = trav_i.order(noarr::slice<'j'>(j_start, inner_len)); // j = 1 .. n-2

			// Forward sweep in j: j = 1 .. n-2
			trav_i_inner.for_each([=](auto state) {
				// state has fixed i and varying j
				const auto prev = state - noarr::idx<'j'>(1); // j-1

				const num_t denom = a * P[prev] + b;
				P[state] = -c / denom;

				const std::size_t j = get_index<'j'>(state);

				// Access neighbours in the orthogonal direction (three-point stencil)
				const num_t u_j_im1 = U[noarr::idx<'i', 'j'>(j, i - 1)];
				const num_t u_j_i   = U[noarr::idx<'i', 'j'>(j, i    )];
				const num_t u_j_ip1 = U[noarr::idx<'i', 'j'>(j, i + 1)];

				Q[state] = (-d * u_j_im1
				            + one_plus_2d * u_j_i
				            - f * u_j_ip1
				            - a * Q[prev]) / denom;
			});

			// Boundary at bottom row
			V[noarr::idx<'i', 'j'>(n_minus_1, i)] = one;

			// Backward sweep in j: j = n-2 .. 1
			// We reuse the same forward j-traverser (k = 1 .. n-2)
			// and map it to descending j = n-1-k to keep dependencies
			// intact (each step depends on j+1 which has already been
			// computed in a previous iteration).
			trav_i_inner.for_each([=](auto state) {
				const std::size_t k = get_index<'j'>(state);
				const std::size_t j = n_minus_1 - k; // yields j = n-2, n-3, ..., 1

				const auto pij_state   = noarr::idx<'i', 'j'>(i,     j    );
				const auto vjp1i_state = noarr::idx<'i', 'j'>(j + 1, i    );

				V[noarr::idx<'i', 'j'>(j, i)] =
					P[pij_state] * V[vjp1i_state] + Q[pij_state];
			});
		}

		// ------------------------------------------------------------------
		// Row sweep
		//
		// Symmetric to the column sweep: for each i in 1..n-2, we perform
		// forward and backward sweeps along j, this time updating U using V.
		// Again, different i-lines are independent and are parallelized.
		// ------------------------------------------------------------------

		auto row_trav = traverser(U, V, P, Q)
			.order(noarr::slice<'i'>(i_start, inner_len)); // i = 1 .. n-2

		#pragma omp parallel for schedule(static)
		for (auto trav_i : row_trav) {
			const auto istate = trav_i.state();
			const std::size_t i = get_index<'i'>(istate);

			// Boundary conditions for this "row" i
			U[noarr::idx<'i', 'j'>(i,        0)] = one;
			P[noarr::idx<'i', 'j'>(i,        0)] = zero;
			Q[noarr::idx<'i', 'j'>(i,        0)] = U[noarr::idx<'i', 'j'>(i, 0)];

			auto trav_i_inner = trav_i.order(noarr::slice<'j'>(j_start, inner_len)); // j = 1 .. n-2

			// Forward sweep in j: j = 1 .. n-2
			trav_i_inner.for_each([=](auto state) {
				const auto prev = state - noarr::idx<'j'>(1); // j-1

				const num_t denom = d * P[prev] + e;
				P[state] = -f / denom;

				const std::size_t j = get_index<'j'>(state);

				const num_t v_im1_j = V[noarr::idx<'i', 'j'>(i - 1, j)];
				const num_t v_i_j   = V[noarr::idx<'i', 'j'>(i,     j)];
				const num_t v_ip1_j = V[noarr::idx<'i', 'j'>(i + 1, j)];

				Q[state] = (-a * v_im1_j
				            + one_plus_2a * v_i_j
				            - c * v_ip1_j
				            - d * Q[prev]) / denom;
			});

			// Boundary at rightmost column
			U[noarr::idx<'i', 'j'>(i, n_minus_1)] = one;

			// Backward sweep in j: j = n-2 .. 1
			trav_i_inner.for_each([=](auto state) {
				const std::size_t k = get_index<'j'>(state);
				const std::size_t j = n_minus_1 - k; // n-2, ..., 1

				const auto pij_state   = noarr::idx<'i', 'j'>(i, j);
				const auto uijp1_state = noarr::idx<'i', 'j'>(i, j + 1);

				U[pij_state] = P[pij_state] * U[uijp1_state] + Q[pij_state];
			});
		}
	}

#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// input data
	auto set_lengths = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);

	auto U = noarr::bag(noarr::scalar<num_t>() ^ tuning.u_layout ^ set_lengths);
	auto V = noarr::bag(noarr::scalar<num_t>() ^ tuning.v_layout ^ set_lengths);
