// NOTE: the algorithm is the standard PolyBench ADI kernel.
// We keep the mathematical structure identical while:
//  - factoring out loop-invariant constants,
//  - improving traversal structure for better cache behavior,
//  - and adding OpenMP parallelization over the independent i-lines.
[[gnu::flatten, gnu::noinline]]
void kernel_adi(std::size_t tsteps, auto U, auto V, auto P, auto Q) {
	using namespace noarr;

	const std::size_t n = U | get_length<'i'>();

#pragma scop

	// -------------------------
	// Precompute scalar factors
	// -------------------------
	const num_t one  = SCALAR_VAL(1.0);
	const num_t two  = SCALAR_VAL(2.0);
	const num_t DX   = one / (num_t)n;
	const num_t DY   = one / (num_t)n;
	const num_t DT   = one / (num_t)tsteps;
	const num_t B1   = SCALAR_VAL(2.0);
	const num_t B2   = SCALAR_VAL(1.0);
	const num_t mul1 = B1 * DT / (DX * DX);
	const num_t mul2 = B2 * DT / (DY * DY);

	const num_t a = -mul1 / SCALAR_VAL(2.0);
	const num_t b = one + mul1;
	const num_t c = a;
	const num_t d = -mul2 / SCALAR_VAL(2.0);
	const num_t e = one + mul2;
	const num_t f = d;

	// Frequently used linear combinations, kept outside inner loops
	const num_t alpha_d = one + two * d; // (1 + 2*d)
	const num_t alpha_a = one + two * a; // (1 + 2*a)

	// Proto-structures for commonly used slices
	auto slice_i_inner = noarr::slice<'i'>(1, n - 2); // i in [1, n-2]
	auto slice_j_inner = noarr::slice<'j'>(1, n - 2); // j in [1, n-2]

	for (std::size_t t = 1; t <= tsteps; t++) {
		// =========================================================
		// Column sweep: for each column i, solve tridiagonal system
		// =========================================================
		auto col_trav = noarr::traverser(U, V, P, Q).order(slice_i_inner);

		// Each column i is independent => parallelize across i
		#pragma omp parallel for schedule(static)
		for (auto trav_i : col_trav) {
			const std::size_t i = noarr::get_index<'i'>(trav_i.state());
			const std::size_t im1 = i - 1;
			const std::size_t ip1 = i + 1;

			// Boundary conditions for column i
			V[noarr::idx<'i', 'j'>(0,     i)] = one;      // v[0][i] = 1
			P[noarr::idx<'i', 'j'>(i,     0)] = SCALAR_VAL(0.0);
			Q[noarr::idx<'i', 'j'>(i,     0)] = V[noarr::idx<'i', 'j'>(0, i)];

			// Forward sweep in j: j = 1 .. n-2
			auto trav_j_fwd = trav_i.order(slice_j_inner);
			trav_j_fwd.for_each([&](auto state) {
				// state has fixed 'i' and varying 'j' in [1, n-2]
				auto prev = state - noarr::idx<'j'>(1);
				const std::size_t j = noarr::get_index<'j'>(state);

				const num_t p_prev = P[prev];
				const num_t denom  = a * p_prev + b;

				P[state] = -c / denom;

				const num_t u_j_im1 = U[noarr::idx<'i', 'j'>(j, im1)];
				const num_t u_j_i   = U[noarr::idx<'i', 'j'>(j, i  )];
				const num_t u_j_ip1 = U[noarr::idx<'i', 'j'>(j, ip1)];

				Q[state] = (-d * u_j_im1
				            + alpha_d * u_j_i
				            - f * u_j_ip1
				            - a * Q[prev]) / denom;
			});

			// Boundary at bottom row
			V[noarr::idx<'i', 'j'>(n - 1, i)] = one; // v[n-1][i] = 1

			// Backward sweep in j: j = n-2 .. 1
			// Implemented as forward sweep over k = 1 .. n-2 with j = n-1-k
			auto trav_j_bwd = trav_i.order(slice_j_inner);
			trav_j_bwd.for_each([&](auto state_k) {
				const std::size_t k = noarr::get_index<'j'>(state_k);
				const std::size_t j = n - 1 - k; // n-2, n-3, ..., 1

				auto pij_state   = noarr::idx<'i', 'j'>(i, j);
				auto vjp1i_state = noarr::idx<'i', 'j'>(j + 1, i);

				V[noarr::idx<'i', 'j'>(j, i)] =
					P[pij_state] * V[vjp1i_state] + Q[pij_state];
			});
		}

		// ======================================================
		// Row sweep: for each row i, solve tridiagonal system
		// ======================================================
		auto row_trav = noarr::traverser(U, V, P, Q).order(slice_i_inner);

		// Each row i is independent => parallelize across i
		#pragma omp parallel for schedule(static)
		for (auto trav_i : row_trav) {
			const std::size_t i = noarr::get_index<'i'>(trav_i.state());
			const std::size_t im1 = i - 1;
			const std::size_t ip1 = i + 1;

			// Boundary conditions for row i
			U[noarr::idx<'i', 'j'>(i, 0)] = one; // u[i][0] = 1
			P[noarr::idx<'i', 'j'>(i, 0)] = SCALAR_VAL(0.0);
			Q[noarr::idx<'i', 'j'>(i, 0)] = U[noarr::idx<'i', 'j'>(i, 0)];

			// Forward sweep in j: j = 1 .. n-2
			auto trav_j_fwd = trav_i.order(slice_j_inner);
			trav_j_fwd.for_each([&](auto state) {
				auto prev = state - noarr::idx<'j'>(1);
				const std::size_t j = noarr::get_index<'j'>(state);

				const num_t p_prev = P[prev];
				const num_t denom  = d * p_prev + e;

				P[state] = -f / denom;

				const num_t v_im1_j = V[noarr::idx<'i', 'j'>(im1, j)];
				const num_t v_i_j   = V[noarr::idx<'i', 'j'>(i,   j)];
				const num_t v_ip1_j = V[noarr::idx<'i', 'j'>(ip1, j)];

				Q[state] = (-a * v_im1_j
				            + alpha_a * v_i_j
				            - c * v_ip1_j
				            - d * Q[prev]) / denom;
			});

			// Boundary at rightmost column
			U[noarr::idx<'i', 'j'>(i, n - 1)] = one; // u[i][n-1] = 1

			// Backward sweep in j: j = n-2 .. 1
			auto trav_j_bwd = trav_i.order(slice_j_inner);
			trav_j_bwd.for_each([&](auto state_k) {
				const std::size_t k = noarr::get_index<'j'>(state_k);
				const std::size_t j = n - 1 - k; // n-2, ..., 1

				auto pij_state   = noarr::idx<'i', 'j'>(i, j);
				auto uijp1_state = noarr::idx<'i', 'j'>(i, j + 1);

