// computation kernel
//
// Optimizations compared to the original version:
//  - All scalar coefficients (DX, DY, DT, a..f) are algebraically simplified to
//    minimize divisions (only one division by tsteps remains).
//  - Common sub‑expressions (1 + 2*d, 1 + 2*a) are precomputed once.
//  - The forward tridiagonal sweeps keep P[i][j-1] and Q[i][j-1] in registers
//    (P_prev, Q_prev) instead of recomputing a previous index state and
//    reloading from memory every iteration.
//  - Reused traversal modifiers (slices over i and j) are created once and
//    reused, avoiding repeated construction of identical proto-structures.
//  - All loop nests over the grid still use Noarr traversers and for_each /
//    for_dims, preserving the original layout-agnostic design.
[[gnu::flatten, gnu::noinline]]
void kernel_adi(std::size_t tsteps, auto U, auto V, auto P, auto Q) {
	using namespace noarr;

	const auto n = U | get_length<'i'>();

	// Precompute scalar coefficients once per kernel call.
	//
	// Original code used:
	//   DX = 1/n; DY = 1/n; DT = 1/tsteps;
	//   mul1 = B1 * DT / (DX*DX);  (B1 = 2)
	//   mul2 = B2 * DT / (DY*DY);  (B2 = 1)
	//
	// Since DX = DY = 1/n, we have:
	//   DX*DX = DY*DY = 1/n^2
	//   B*DT / (DX*DX) = B*DT*n^2
	//
	// So we can compute mul1, mul2 without ever forming DX or DY and with only
	// one division (for DT).
	const num_t n_f  = static_cast<num_t>(n);
	const num_t n_sq = n_f * n_f;

	const num_t DT   = SCALAR_VAL(1.0) / static_cast<num_t>(tsteps);
	const num_t mul1 = SCALAR_VAL(2.0) * DT * n_sq; // B1 = 2.0
	const num_t mul2 = SCALAR_VAL(1.0) * DT * n_sq; // B2 = 1.0

	// Tridiagonal coefficients in both directions.
	const num_t a = -SCALAR_VAL(0.5) * mul1;
	const num_t b = SCALAR_VAL(1.0) + mul1;
	const num_t c = a;

	const num_t d = -SCALAR_VAL(0.5) * mul2;
	const num_t e = SCALAR_VAL(1.0) + mul2;
	const num_t f = d;

	// Common constants and combinations used inside the sweeps.
	const num_t one           = SCALAR_VAL(1.0);
	const num_t two           = SCALAR_VAL(2.0);
	const num_t one_plus_2d   = one + two * d;
	const num_t one_plus_2a   = one + two * a;

	// Reusable slicing proto-structures for interior points (1 .. n-2).
	const auto inner_i_slice = noarr::slice<'i'>(1, n - 2);
	const auto inner_j_slice = noarr::slice<'j'>(1, n - 2);

#pragma scop
	for (std::size_t t = 1; t <= tsteps; t++) {
		// -------------------------------------------------------------------
		// Column sweep: for each interior i, sweep along j
		// -------------------------------------------------------------------
		traverser(U, V, P, Q)
			.order(inner_i_slice)
			.template for_dims<'i'>([=](auto trav_i) {
				const auto i = get_index<'i'>(trav_i.state());

				// Boundary conditions for column i
				V[noarr::idx<'i', 'j'>(0, i)] = one;
				P[noarr::idx<'i', 'j'>(i, 0)] = SCALAR_VAL(0.0);
				Q[noarr::idx<'i', 'j'>(i, 0)] = V[noarr::idx<'i', 'j'>(0, i)];

				// Keep P[i][j-1] and Q[i][j-1] in registers.
				num_t P_prev = P[noarr::idx<'i', 'j'>(i, 0)];
				num_t Q_prev = Q[noarr::idx<'i', 'j'>(i, 0)];

				// Forward sweep in j: j = 1 .. n-2
				trav_i.order(inner_j_slice).for_each(
					[=, &P_prev, &Q_prev](auto state) {
						const auto j = get_index<'j'>(state);

						const num_t denom = a * P_prev + b;
						const num_t P_cur = -c / denom;

						const num_t u_j_im1 = U[noarr::idx<'i', 'j'>(j, i - 1)];
						const num_t u_j_i   = U[noarr::idx<'i', 'j'>(j, i    )];
						const num_t u_j_ip1 = U[noarr::idx<'i', 'j'>(j, i + 1)];

						const num_t Q_cur =
							(-d * u_j_im1
							 + one_plus_2d * u_j_i
							 - f * u_j_ip1
							 - a * Q_prev) / denom;

						// Update arrays and carry the current values as "previous"
						// for the next j.
						P[state] = P_prev = P_cur;
						Q[state] = Q_prev = Q_cur;
					});

				// Boundary at bottom row
				V[noarr::idx<'i', 'j'>(n - 1, i)] = one;

				// Backward sweep in j: j = n-2 .. 1
				// Implemented as forward sweep over k = 1 .. n-2 with j = n-1-k
				trav_i.order(inner_j_slice).for_each(
					[=](auto state) {
						const auto k = get_index<'j'>(state);
						const std::size_t j = n - 1 - k; // n-2, n-3, ..., 1

						const auto pij_state   = noarr::idx<'i', 'j'>(i, j);
						const auto vjp1i_state = noarr::idx<'i', 'j'>(j + 1, i);

						V[noarr::idx<'i', 'j'>(j, i)] =
							P[pij_state] * V[vjp1i_state] + Q[pij_state];
					});
			});

		// -------------------------------------------------------------------
		// Row sweep: for each interior i, sweep along j
		// -------------------------------------------------------------------
		traverser(U, V, P, Q)
			.order(inner_i_slice)
			.template for_dims<'i'>([=](auto trav_i) {
				const auto i = get_index<'i'>(trav_i.state());

				// Boundary conditions for row i
				U[noarr::idx<'i', 'j'>(i, 0)] = one;
				P[noarr::idx<'i', 'j'>(i, 0)] = SCALAR_VAL(0.0);
				Q[noarr::idx<'i', 'j'>(i, 0)] = U[noarr::idx<'i', 'j'>(i, 0)];

				// Keep P[i][j-1] and Q[i][j-1] in registers.
				num_t P_prev = P[noarr::idx<'i', 'j'>(i, 0)];
				num_t Q_prev = Q[noarr::idx<'i', 'j'>(i, 0)];

				// Forward sweep in j: j = 1 .. n-2
				trav_i.order(inner_j_slice).for_each(
					[=, &P_prev, &Q_prev](auto state) {
						const auto j = get_index<'j'>(state);

						const num_t denom = d * P_prev + e;
						const num_t P_cur = -f / denom;

						const num_t v_im1_j = V[noarr::idx<'i', 'j'>(i - 1, j)];
						const num_t v_i_j   = V[noarr::idx<'i', 'j'>(i    , j)];
						const num_t v_ip1_j = V[noarr::idx<'i', 'j'>(i + 1, j)];

						const num_t Q_cur =
							(-a * v_im1_j
							 + one_plus_2a * v_i_j
							 - c * v_ip1_j
							 - d * Q_prev) / denom;

						// Update arrays and carry the current values as "previous"
						// for the next j.
						P[state] = P_prev = P_cur;
						Q[state] = Q_prev = Q_cur;
					});

				// Boundary at rightmost column
				U[noarr::idx<'i', 'j'>(i, n - 1)] = one;

				// Backward sweep in j: j = n-2 .. 1
				trav_i.order(inner_j_slice).for_each(
					[=](auto state) {
						const auto k = get_index<'j'>(state);
						const std::size_t j = n - 1 - k; // n-2, ..., 1

						const auto pij_state   = noarr::idx<'i', 'j'>(i, j);
						const auto uijp1_state = noarr::idx<'i', 'j'>(i, j + 1);

						U[pij_state] = P[pij_state] * U[uijp1_state] + Q[pij_state];
					});
			});
	}
#pragma endscop
}

